INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-house-blend', 'House Blend', 'house-blend', 'A dependable, rounded espresso-friendly blend for everyday cafe service. Roasted for balance across batch brew and bar service.', ARRAY['Chocolate','Hazelnut','Brown sugar']::text[], 'Blend', 'blends', 'Your everyday house espresso and milk drink base.', 'Medium', '/mockups/bag-kraft.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-espresso-blend', 'Espresso Blend', 'espresso-blend', 'A bold profile built for milk drinks, consistent crema, and a classic finish. Works on traditional and modern espresso setups.', ARRAY['Dark cocoa','Caramel','Roasted almond']::text[], 'Blend', 'blends', 'Built for crema, body, and flat whites.', 'Medium–dark', '/mockups/bag-black.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-morning-filter', 'Morning Filter Blend', 'morning-filter-blend', 'A medium roast blend tuned for batch brew, pour-over, and filter service. Designed to taste approachable from first cup to last.', ARRAY['Milk chocolate','Red apple','Light caramel']::text[], 'Blend', 'blends', 'Sweet, clean, and forgiving on batch brew.', 'Medium', '/mockups/bag-white.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-ethiopia-yirgacheffe', 'Ethiopia Yirgacheffe', 'ethiopia-yirgacheffe', 'Classic washed Yirgacheffe with pronounced florals and citrus. Ideal when you want a named origin on your white-label line.', ARRAY['Jasmine','Bergamot','Lemon zest']::text[], 'Single origin', 'single-origin', 'Floral washed lot for distinctive shelves.', 'Light', '/mockups/bag-white.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-colombia-huila', 'Colombia Huila', 'colombia-huila', 'Huila lot with ripe stone fruit and clean sweetness. Versatile across espresso and filter without chasing extremes.', ARRAY['Peach','Panela','Milk chocolate']::text[], 'Single origin', 'single-origin', 'Balanced sweetness for omni service.', 'Medium', '/mockups/bag-kraft.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-brazil-santos', 'Brazil Santos', 'brazil-santos', 'Low-acid, full-bodied profile with nut and cocoa notes. Popular as a single-origin espresso or as the base of a custom blend.', ARRAY['Peanut brittle','Cocoa','Dried fig']::text[], 'Single origin', 'single-origin', 'Nutty base for espresso blends or solo service.', 'Medium', '/mockups/bag-kraft.svg', true);
